#include <vector>
#include <string>
#include <algorithm>
struct Request{int at,replica,duration;bool leak=false;std::string state="future";int start=-1,end=-1;};struct Connection{int replica,request=-1;bool leaked=false;};
struct Pool{int poolSize,databaseLimit;std::vector<Connection>connections;bool acquire(std::vector<Request>&requests,int id,int tick){auto& r=requests[id];int slot=-1,owned=0;for(unsigned i=0;i<connections.size();i++)if(connections[i].replica==r.replica){owned++;if(connections[i].request<0&&!connections[i].leaked)slot=i;}if(slot<0&&int(connections.size())<databaseLimit&&owned<poolSize){slot=connections.size();connections.push_back({r.replica,-1,false});}if(slot<0)return false;connections[slot].request=id;r.state="running";r.start=tick;r.end=tick+r.duration;return true;}
void run(std::vector<Request>&requests,int ticks,int timeout,int queueLimit){for(int tick=0;tick<ticks;tick++){for(auto&c:connections)if(c.request>=0&&!c.leaked){auto& r=requests[c.request];if(r.end<=tick){r.state="done";if(r.leak)c.leaked=true;else c.request=-1;}}for(auto&r:requests)if(r.state=="waiting"&&tick-r.at>=timeout)r.state="timeout";std::vector<int>waitingIds;for(unsigned i=0;i<requests.size();i++)if(requests[i].state=="waiting")waitingIds.push_back(i);std::sort(waitingIds.begin(),waitingIds.end(),[&](int a,int b){return requests[a].at!=requests[b].at?requests[a].at<requests[b].at:a<b;});for(int id:waitingIds)acquire(requests,id,tick);for(unsigned id=0;id<requests.size();id++){auto&r=requests[id];if(r.state!="future"||r.at!=tick)continue;int waiting=0;for(auto other:requests)if(other.state=="waiting"&&other.replica==r.replica)waiting++;if(waiting||!acquire(requests,id,tick))r.state=waiting>=queueLimit?"rejected":"waiting";}}}};
// No real sockets: bounded requests and replica-owned capacity expose timeout/leak behavior.
